import React from 'react';

import { Link } from 'react-router-dom';

import { dateRangeToLocaleString } from '@helpers/dateHelper';
import PohAva from '@ui-kit/Ava';
import PohBadge from '@ui-kit/Badge/Badge';
import Empty from '@ui-kit/Empty';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';

import { getHikingObstaclesByObstacleId } from '../../../Hiking/@services/hikingObstacles.service';
import { IHikingObstacleWithHikingListItem } from '../../../Hiking/@types/hikingObstacles.types';

interface IObstacleHikingPassProps {
  id_obstacle: number;
}

const ObstacleHikingPass: React.FC<IObstacleHikingPassProps> = ({ id_obstacle }) => {
  const [data, setData] = React.useState<IHikingObstacleWithHikingListItem[]>([]);
  const [isLoading, setIsLoading] = React.useState<boolean>(false);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const dataRes = await getHikingObstaclesByObstacleId(id_obstacle);
        setData(dataRes);
      } finally {
        setIsLoading(false);
      }
    };
    start();
  }, [id_obstacle]);

  if (isLoading) return null;

  return (
    <>
      <PohRow className="mt-3">
        <PohCol sm={12}>
          <h4>
            Отметки о прохождении{' '}
            <small>
              <PohBadge rounded>{data.length}</PohBadge>
            </small>
          </h4>
        </PohCol>
      </PohRow>
      <PohRow className="">
        <PohCol sm={12}>
          {data.length ? (
            <PohList
              data={data.map((d) => {
                return {
                  key: d.id,
                  children: (
                    <Link
                      to={`/hiking/${d.hiking.id}/obstacles/${id_obstacle}/${d.id}`}
                      className="d-flex align-items-center"
                      style={{ lineHeight: 1 }}
                    >
                      <PohAva colorize alt={d.hiking.name} src={d.hiking.ava} />
                      <div className="ms-2">
                        <strong className="d-block">{d.hiking.name}</strong>
                        <small className="d-block">
                          Поход: {dateRangeToLocaleString(d.hiking.start, d.hiking.finish)}
                        </small>
                        <small>Прохождение: {dateRangeToLocaleString(d.date_in, d.date_out)}</small>
                      </div>
                    </Link>
                  ),
                };
              })}
            />
          ) : (
            <Empty>Нет отметок о прохождении</Empty>
          )}
        </PohCol>
      </PohRow>
    </>
  );
};

export default ObstacleHikingPass;
