import React from 'react';

import MapPoint from '@components/MapPoint';
import PageLoader from '@components/PageLoader';
import { formatAltitude } from '@helpers/formatHelper';
import PohAlert from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import ObstacleHikingPass from './ObstacleHikingPass';
import { getUrlFromObstacleType } from '../../@mappers/obstacles.url.mapper';
import {
  obstacleTypeNameResource,
  obstacleTypeUrlNameResource,
} from '../../@resources/obstacles.resource';
import { getOneObstacleAsync } from '../../@services/obstacles.service';
import { IObstacle } from '../../@types/obstacles.types';
import ObstacleCategoryBadge from '../ObstacleCategoryBadge/ObstacleCategoryBadge';
import { editObstacleModalAsync } from '../ObstacleModal/modalHelper';

interface IObstacleOnePageProps {
  id: number;
}

const ObstacleOnePage: React.FC<IObstacleOnePageProps> = ({ id }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IObstacle>();
  const [err, setErr] = React.useState<string | undefined>(undefined);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const d = await getOneObstacleAsync(id);
        setData(d);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert>{err}</PohAlert>;
  }

  const handleEdit = () => {
    if (!data) return;
    editObstacleModalAsync(data).then(setData);
  };

  if (!data) {
    return <PohAlert>No data</PohAlert>;
  }

  const captionSize = 3;
  const contentSize = 9;

  const typeFromUrl = getUrlFromObstacleType(data.type);
  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/obstacles', text: 'Локальные препятствия' },
          { href: `/obstacles/${typeFromUrl}`, text: obstacleTypeUrlNameResource[typeFromUrl] },
          { href: `/obstacles/${typeFromUrl}/${data.id}`, text: data.name, active: true },
        ]}
      />
      <PohContainer>
        <header className="d-flex justify-content-between align-items-center d-print-none">
          <h3 className="mb-3">{data.name}</h3>
          <PohButton size={ButtonSize.Small} variant={ButtonVariant.Success} onClick={handleEdit}>
            Редактировать
          </PohButton>
        </header>
        <PohRow>
          <PohCol sm={5}>
            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Тип:
              </PohCol>
              <PohCol sm={contentSize}>{obstacleTypeNameResource[data.type]}</PohCol>
            </PohRow>
            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Название:
              </PohCol>
              <PohCol sm={contentSize}>
                <strong>{data.name}</strong>
              </PohCol>
            </PohRow>
            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Категория:
              </PohCol>
              <PohCol sm={contentSize}>
                <ObstacleCategoryBadge category={data.category} />
              </PohCol>
            </PohRow>
            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Высота:
              </PohCol>
              <PohCol sm={contentSize}>{formatAltitude(data.altitude)}</PohCol>
            </PohRow>
            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Регион:
              </PohCol>
              <PohCol sm={contentSize}>{data.region?.name}</PohCol>
            </PohRow>
          </PohCol>
          <PohCol sm={7}>
            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Комментарий:
              </PohCol>
              <PohCol sm={contentSize}>{data.comment}</PohCol>
            </PohRow>
            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Описание:
              </PohCol>
              <PohCol sm={contentSize}>{data.description}</PohCol>
            </PohRow>
            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Ссылка:
              </PohCol>
              <PohCol sm={contentSize}>
                <a target="_blank" href={data.link} rel="noreferrer">
                  {data.link}
                </a>{' '}
              </PohCol>
            </PohRow>
            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Координаты:
              </PohCol>
              <PohCol sm={contentSize}>
                <a href={`geo:${data.coordinates}`} target="_blank" rel="noreferrer">
                  {data.coordinates.join(', ')}
                </a>{' '}
              </PohCol>
            </PohRow>

            <PohRow className="mb-2">
              <PohCol sm={captionSize} className="text-muted text-sm-end">
                Создано:
              </PohCol>
              <PohCol sm={contentSize}>
                {data.created.date.toLocaleString()} {data.created.name}
              </PohCol>
            </PohRow>
            {data.updated && (
              <PohRow className="mb-2">
                <PohCol sm={captionSize} className="text-muted text-sm-end">
                  Обновлено:
                </PohCol>
                <PohCol sm={contentSize}>
                  {data.updated.date.toLocaleString()} {data.updated.name}
                </PohCol>
              </PohRow>
            )}
          </PohCol>
        </PohRow>
        <PohRow className="mt-3">
          <PohCol sm={12}>
            <MapPoint point={data.coordinates} height={200} />
          </PohCol>
        </PohRow>
        <ObstacleHikingPass id_obstacle={id} />
      </PohContainer>
    </div>
  );
};

export default ObstacleOnePage;
